    void outOfLimitDifferentialSavedButNotReleasable() throws Exception {
        setupSyntheticPair();

        // 差值 0.3 超出上限 0.2：不合格差分仍保存为待审
        createDiff("RQ-L1", "DIFF-L1", "D-REF", "D-DUT", "0", "0.2", "carol")
                .andExpect(status().isCreated())
