    void revokedReferenceCertificateBlocksWholeRelease() throws Exception {
        // 两条测量各用不同有效证书（相邻区间，采样跨越边界 4 秒）
        long refCert = createCert("INS-V", "2026-01-01T00:00:00Z", "2026-07-01T00:00:00Z", "1", "0");
