/** 并发执行 n 个任务并收集 HTTP 状态码。 */
private List<Integer> runConcurrently(int threads, java.util.concurrent.Callable<Integer> task)
        throws Exception {
    ExecutorService pool = Executors.newFixedThreadPool(threads);
    CountDownLatch start = new CountDownLatch(1);
    List<Future<Integer>> futures = new ArrayList<>();
    for (int i = 0; i < threads; i++) {
        futures.add(pool.submit(() -> {
            start.await();
            return task.call();
        }));
    }
    start.countDown();
    List<Integer> statuses = new ArrayList<>();
    for (Future<Integer> future : futures) {
        statuses.add(future.get(30, TimeUnit.SECONDS));
    }
    pool.shutdown();
    return statuses;
}

private long countOf(List<Integer> statuses, int expected) {
    return statuses.stream().filter(s -> s == expected).count();
}

